import React, { useEffect, useState } from "react";
import Sidebar from "../components/Sidebar";

function Dashboard() {
  const [stats, setStats] = useState(null);
  const [upcomingSessions, setUpcomingSessions] = useState([]);
  const [recentActivity, setRecentActivity] = useState([]);
  const [loading, setLoading] = useState(true);
  const [currentMonth, setCurrentMonth] = useState(new Date());

  const user = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    if (!user) return;

    // Get user's actual stats from localStorage
    const userStats = {
      xp: user.xp || 0,
      coins: user.coins || 0,
      streak: user.streak || 0,
      lessonsCompleted: user.lessonsCompleted || 0,
      lessonsInProgress: user.lessonsInProgress || 0,
      totalGameScore: user.totalGameScore || 0,
    };

    // Get stored activity and sessions
    const storedActivity = JSON.parse(localStorage.getItem("userActivity")) || [];
    const storedSessions = JSON.parse(localStorage.getItem("userSessions")) || [];

    setStats(userStats);
    setRecentActivity(storedActivity.slice(0, 5)); // Show 5 most recent
    setUpcomingSessions(storedSessions);
    setLoading(false);

    // Listen for dashboard updates from other pages
    const handleDashboardUpdate = (event) => {
      console.log("📊 Dashboard update received:", event.detail);
      const { type, activity, session, stats: newStats } = event.detail;

      // Update stats if provided
      if (newStats) {
        setStats(prev => ({ ...prev, ...newStats }));
        // Update user in localStorage
        const updatedUser = { ...user, ...newStats };
        localStorage.setItem("user", JSON.stringify(updatedUser));
      }

      // Add new activity
      if (activity) {
        setRecentActivity(prev => [activity, ...prev.slice(0, 4)]);
        // Save to localStorage
        const activities = JSON.parse(localStorage.getItem("userActivity")) || [];
        localStorage.setItem("userActivity", JSON.stringify([activity, ...activities]));
      }

      // Add new session
      if (session) {
        setUpcomingSessions(prev => [session, ...prev]);
        // Save to localStorage
        const sessions = JSON.parse(localStorage.getItem("userSessions")) || [];
        localStorage.setItem("userSessions", JSON.stringify([session, ...sessions]));
      }

      console.log(`✅ Dashboard updated: ${type}`);
    };

    window.addEventListener("dashboardUpdate", handleDashboardUpdate);

    return () => window.removeEventListener("dashboardUpdate", handleDashboardUpdate);
  }, [user]);

  // Calendar helper functions
  const getDaysInMonth = (date) => new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  const getFirstDayOfMonth = (date) => new Date(date.getFullYear(), date.getMonth(), 1).getDay();

  const renderCalendar = () => {
    const daysInMonth = getDaysInMonth(currentMonth);
    const firstDay = getFirstDayOfMonth(currentMonth);
    const days = [];

    for (let i = 0; i < firstDay; i++) {
      days.push(<div key={`empty-${i}`} className="calendar-day empty"></div>);
    }

    for (let i = 1; i <= daysInMonth; i++) {
      const isToday = i === new Date().getDate() && currentMonth.getMonth() === new Date().getMonth();
      days.push(
        <div key={i} className={`calendar-day ${isToday ? "today" : ""}`}>
          {i}
        </div>
      );
    }

    return days;
  };

  if (!user) {
    return <h1 style={{ color: "white" }}>Please log in</h1>;
  }

  const lessonProgress = stats ? (stats.lessonsCompleted / (stats.lessonsCompleted + stats.lessonsInProgress)) * 100 : 0;
  const xpProgress = stats ? (stats.xp % 1000) / 10 : 0;

  return (
    <div className="dashboard-page">
      <Sidebar />

      <main className="dashboard-main" style={{ padding: "2rem", maxWidth: "100%" }}>
        {/* HERO SECTION */}
        <header style={{
          background: "linear-gradient(135deg, rgba(14, 165, 233, 0.1) 0%, rgba(56, 189, 248, 0.05) 100%)",
          border: "1px solid rgba(56, 189, 248, 0.2)",
          backdropFilter: "blur(10px)",
          borderRadius: "16px",
          padding: "2rem",
          marginBottom: "3rem",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}>
          <div>
            <h1 style={{ fontSize: "2.5rem", color: "#f9fafb", marginBottom: "0.5rem", fontWeight: "700" }}>
              Welcome back, {user.firstName}! 👋
            </h1>
            <p style={{ fontSize: "1.1rem", color: "#9ca3af" }}>
              Keep up your streak and continue mastering new subjects
            </p>
          </div>
          <div style={{ textAlign: "center" }}>
            <div style={{ fontSize: "3.5rem", fontWeight: "700", color: "#fcd34d" }}>
              🔥 {stats?.streak || 0}
            </div>
            <div style={{ color: "#9ca3af", fontSize: "0.9rem" }}>Day Streak</div>
          </div>
        </header>

        {loading ? (
          <p style={{ color: "#9ca3af", textAlign: "center" }}>Loading...</p>
        ) : stats ? (
          <>
            {/* TOP STATS ROW */}
            <div style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
              gap: "1.5rem",
              marginBottom: "2rem",
            }}>
              {/* XP Card */}
              <div style={{
                background: "linear-gradient(135deg, rgba(34, 197, 94, 0.1) 0%, rgba(22, 163, 74, 0.05) 100%)",
                border: "1px solid rgba(34, 197, 94, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <div style={{ color: "#9ca3af", fontSize: "0.9rem", marginBottom: "0.5rem" }}>📊 Total XP</div>
                <div style={{ fontSize: "2rem", fontWeight: "700", color: "#86efac", marginBottom: "1rem" }}>
                  {stats.xp || 0}
                </div>
                <div style={{ background: "rgba(0,0,0,0.2)", borderRadius: "8px", height: "6px", overflow: "hidden" }}>
                  <div style={{
                    width: `${xpProgress}%`,
                    height: "100%",
                    background: "linear-gradient(90deg, #86efac, #22c55e)",
                    transition: "width 0.3s ease",
                  }}></div>
                </div>
                <div style={{ color: "#6b7280", fontSize: "0.75rem", marginTop: "0.5rem" }}>
                  {Math.floor(stats.xp % 1000)} / 1000
                </div>
              </div>

              {/* Coins Card */}
              <div style={{
                background: "linear-gradient(135deg, rgba(252, 211, 77, 0.1) 0%, rgba(217, 119, 6, 0.05) 100%)",
                border: "1px solid rgba(252, 211, 77, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <div style={{ color: "#9ca3af", fontSize: "0.9rem", marginBottom: "0.5rem" }}>💰 Coins</div>
                <div style={{ fontSize: "2rem", fontWeight: "700", color: "#fcd34d", marginBottom: "1rem" }}>
                  {stats.coins}
                </div>
                <div style={{ color: "#6b7280", fontSize: "0.85rem" }}>
                  💎 Next Reward: 50 coins
                </div>
              </div>

              {/* Lessons Card */}
              <div style={{
                background: "linear-gradient(135deg, rgba(59, 130, 246, 0.1) 0%, rgba(37, 99, 235, 0.05) 100%)",
                border: "1px solid rgba(59, 130, 246, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <div style={{ color: "#9ca3af", fontSize: "0.9rem", marginBottom: "0.5rem" }}>📚 Lessons</div>
                <div style={{ fontSize: "2rem", fontWeight: "700", color: "#60a5fa", marginBottom: "1rem" }}>
                  {stats.lessonsCompleted}/{stats.lessonsCompleted + stats.lessonsInProgress}
                </div>
                <div style={{ background: "rgba(0,0,0,0.2)", borderRadius: "8px", height: "6px", overflow: "hidden" }}>
                  <div style={{
                    width: `${lessonProgress}%`,
                    height: "100%",
                    background: "linear-gradient(90deg, #60a5fa, #3b82f6)",
                    transition: "width 0.3s ease",
                  }}></div>
                </div>
                <div style={{ color: "#6b7280", fontSize: "0.75rem", marginTop: "0.5rem" }}>
                  {Math.floor(lessonProgress)}% Complete
                </div>
              </div>

              {/* Game Score Card */}
              <div style={{
                background: "linear-gradient(135deg, rgba(168, 85, 247, 0.1) 0%, rgba(126, 34, 206, 0.05) 100%)",
                border: "1px solid rgba(168, 85, 247, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <div style={{ color: "#9ca3af", fontSize: "0.9rem", marginBottom: "0.5rem" }}>🎮 Game Score</div>
                <div style={{ fontSize: "2rem", fontWeight: "700", color: "#d8b4fe", marginBottom: "1rem" }}>
                  {stats.totalGameScore || 0}
                </div>
                <div style={{ color: "#6b7280", fontSize: "0.85rem" }}>
                  📈 +250 this week
                </div>
              </div>
            </div>

            {/* MIDDLE SECTION - CALENDAR & ACTIVITY CHART */}
            <div style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "1.5rem",
              marginBottom: "2rem",
            }}>
              {/* CALENDAR */}
              <div style={{
                background: "rgba(15, 23, 42, 0.5)",
                border: "1px solid rgba(148, 163, 184, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.5rem" }}>
                  <h3 style={{ color: "#f9fafb", fontSize: "1.2rem", fontWeight: "600" }}>📅 Calendar</h3>
                  <div style={{ display: "flex", gap: "0.5rem" }}>
                    <button onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1))}
                      style={{
                        padding: "5px 10px",
                        background: "rgba(148, 163, 184, 0.1)",
                        border: "1px solid rgba(148, 163, 184, 0.2)",
                        color: "#9ca3af",
                        borderRadius: "6px",
                        cursor: "pointer",
                      }}>←</button>
                    <button onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1))}
                      style={{
                        padding: "5px 10px",
                        background: "rgba(148, 163, 184, 0.1)",
                        border: "1px solid rgba(148, 163, 184, 0.2)",
                        color: "#9ca3af",
                        borderRadius: "6px",
                        cursor: "pointer",
                      }}>→</button>
                  </div>
                </div>
                <div style={{ color: "#9ca3af", marginBottom: "1rem", textAlign: "center", fontSize: "0.95rem", fontWeight: "600" }}>
                  {currentMonth.toLocaleString("default", { month: "long", year: "numeric" })}
                </div>
                <div style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(7, 1fr)",
                  gap: "0.5rem",
                }}>
                  {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => (
                    <div key={day} style={{ color: "#6b7280", fontSize: "0.75rem", textAlign: "center", fontWeight: "600" }}>
                      {day}
                    </div>
                  ))}
                  {renderCalendar()}
                </div>
                <style>{`
                  .calendar-day {
                    padding: 8px;
                    background: rgba(148, 163, 184, 0.1);
                    border-radius: 6px;
                    color: #9ca3af;
                    textAlign: center;
                    fontSize: 0.85rem;
                    cursor: pointer;
                    transition: all 0.2s;
                  }
                  .calendar-day:hover {
                    background: rgba(56, 189, 248, 0.2);
                    color: #38bdf8;
                  }
                  .calendar-day.today {
                    background: linear-gradient(135deg, #38bdf8, #0ea5e9);
                    color: white;
                    fontWeight: 700;
                  }
                  .calendar-day.empty {
                    background: transparent;
                    cursor: default;
                  }
                  .calendar-day.empty:hover {
                    background: transparent;
                    color: #9ca3af;
                  }
                `}</style>
              </div>

              {/* ACHIEVEMENT BADGES */}
              <div style={{
                background: "rgba(15, 23, 42, 0.5)",
                border: "1px solid rgba(148, 163, 184, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <h3 style={{ color: "#f9fafb", fontSize: "1.2rem", fontWeight: "600", marginBottom: "1.5rem" }}>🏆 Achievements</h3>
                <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: "1rem" }}>
                  <div style={{
                    padding: "1rem",
                    background: "rgba(34, 197, 94, 0.1)",
                    border: "1px solid rgba(34, 197, 94, 0.3)",
                    borderRadius: "8px",
                    textAlign: "center",
                  }}>
                    <div style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>🌟</div>
