                    <div style={{ color: "#6b7280", fontSize: "0.75rem" }}>7 Day Streak</div>
                  </div>
                  <div style={{
                    padding: "1rem",
                    background: "rgba(59, 130, 246, 0.1)",
                    border: "1px solid rgba(59, 130, 246, 0.3)",
                    borderRadius: "8px",
                    textAlign: "center",
                  }}>
                    <div style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>🎮</div>
                    <div style={{ color: "#9ca3af", fontSize: "0.85rem", fontWeight: "600" }}>Game Master</div>
                    <div style={{ color: "#6b7280", fontSize: "0.75rem" }}>3000+ Score</div>
                  </div>
                  <div style={{
                    padding: "1rem",
                    background: "rgba(168, 85, 247, 0.1)",
                    border: "1px solid rgba(168, 85, 247, 0.3)",
                    borderRadius: "8px",
                    textAlign: "center",
                  }}>
                    <div style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>📚</div>
                    <div style={{ color: "#9ca3af", fontSize: "0.85rem", fontWeight: "600" }}>Scholar</div>
